import{_ as p,a0 as l,w as s,s as a,ao as i,I as r,x as e,a1 as n,A as u}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const _=JSON.parse('{"title":"每日 Ubuntu 小技巧——以色辨夹 | LCTT x X-CMD","titleTemplate":false,"description":"每日 Ubuntu 小技巧——以色辨夹 | LCTT (201405) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每日 Ubuntu 小技巧——以色辨夹 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每日 Ubuntu 小技巧——以色辨夹 | LCTT (201405) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201405/Daily Ubuntu Tips – Identify Folders By Colors In Ubuntu","title":"每日 Ubuntu 小技巧——以色辨夹","tag":"201405","desc":""},"relativePath":"201405/Daily Ubuntu Tips – Identify Folders By Colors In Ubuntu.md","filePath":"[post].md"}'),d={name:"201405/Daily Ubuntu Tips – Identify Folders By Colors In Ubuntu.md"};function b(f,t,m,T,C,g){const o=l("Link");return s(),a("div",null,[t[11]||(t[11]=i(`<h1 id="每日-ubuntu-小技巧——以色辨夹" tabindex="-1">每日 Ubuntu 小技巧——以色辨夹 <a class="header-anchor" href="#每日-ubuntu-小技巧——以色辨夹" aria-label="Permalink to “每日 Ubuntu 小技巧——以色辨夹”">​</a></h1><p>这篇简短的文章将教会你如何在Ubuntu 14.04或者其先前版本中使用美化工具来实现通过颜色分辨文件夹。这个工具就是<strong>Folder Color</strong>,它允许用户改变 Nautilus 文件浏览器中文件夹的颜色，这样就可以让用户很容易地识别并区分它们。</p><p>这个工具的开发者设计初衷是与 Nautilus 配合使用，其实它也可以与Ubuntu上其它的图标主题配合使用。这是一个很好的工具，轻量级，不会影响你的系统的性能。</p><p>这个软件安装起来方便，让下面这个简短的教程告诉你如何做吧。</p><p>假如你想将重要的文件夹设置成红色的，或者将文档文件夹设置为黄色，你可以用Folder Color轻松地更改它们的颜色。</p><p>接下来教你来安装这个工具。</p><p>在Ubuntu 中<strong>Ctrl - Alt - T</strong>打开终端。添加下面的PPA源。</p><pre><code>sudo add-apt-repository ppa:costales/folder-color
</code></pre><p>然后运行下面的命令更新你的系统并安装Folder Color。</p><pre><code>sudo apt-get update &amp;&amp; sudo apt-get install folder-color
</code></pre><p>这样安装就可以了。现在你要做的就是注销登录然后再次登入系统或者重新启动Nautilus 。打开Nautilus，在你想改变颜色的文件夹上右键单击选择你想要的颜色。这些是预先定义的颜色，或许无法满足你的需要，但是对于大多数用户来说这足够了。</p><p>如果你想卸载它，运行下面的命令移除PPA源。</p><pre><code>sudo add-apt-repository -r ppa:costales/folder-color
</code></pre><p>最后，运行下面的命令移除Folder Color 。</p><pre><code>sudo apt-get update &amp;&amp; sudo apt-get remove folder-color
</code></pre><p>使用愉快！</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2014/04/foldercolorubuntu.png" alt=""></p><hr>`,18)),r("p",null,[t[1]||(t[1]=e("via: ",-1)),n(o,{href:"http://www.liberiangeek.net/2014/04/daily-ubuntu-tips-identify-folders-by-colors-in-ubuntu/"},{default:u(()=>[...t[0]||(t[0]=[e("http://www.liberiangeek.net/2014/04/daily-ubuntu-tips-identify-folders-by-colors-in-ubuntu/",-1)])]),_:1})]),r("p",null,[t[4]||(t[4]=e("译者：",-1)),n(o,{href:"https://github.com/Linchenguang"},{default:u(()=>[...t[2]||(t[2]=[e("Linchenguang",-1)])]),_:1}),t[5]||(t[5]=e(" 校对：",-1)),n(o,{href:"https://github.com/carolinewuyan"},{default:u(()=>[...t[3]||(t[3]=[e("Caroline",-1)])]),_:1})]),r("p",null,[t[8]||(t[8]=e("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:u(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原创翻译，",-1)),n(o,{href:"http://linux.cn/"},{default:u(()=>[...t[7]||(t[7]=[e("Linux中国",-1)])]),_:1}),t[10]||(t[10]=e(" 荣誉推出",-1))])])}const w=p(d,[["render",b]]);export{_ as __pageData,w as default};
